import json
import logging as logger
import os
import re
from io import BytesIO
from zipfile import ZipFile

from .exceptions import FileSizeEqualZero, InvalidSnapshotException, NotFoundMandatoryFile


class SnapshotCrawler(object):
    def verify_snapshot(self, snapshot_path, paths_to_check):
        """
        :param snapshot_path: absolute or relative path to the snapshot zipFile
        :param paths_to_check: list of paths to verify.
        The path should contain also zip files in which files and directories were packed, example:
        ['RAC/racoam_snapshot.zip/RAC/RACLogFiles/BIM/RacOAM/racoam_runtime_bim.json']
        :return: InvalidSnapshotException if file from paths_to_check is not in snapshot or is empty
        """
        return self._verify_snapshot(snapshot_path, paths_to_check)

    def _verify_snapshot(self, snapshot_path, paths_to_check):
        paths_split = [path.split("/") for path in paths_to_check]
        tree = self._build_tree_from_paths(snapshot_path, paths_split)
        self._verify_paths_in_snapshot(tree.root, snapshot_path)

    def _build_tree_from_paths(self, snapshot_path, paths_split):
        tree = Tree(snapshot_path)
        for path in paths_split:
            tree.add(path)
        return tree

    def _verify_paths_in_snapshot(self, node, current_zip, path_inside_zip="", full_path=""):
        if len(node.children) > 0:
            for child in node.children:
                path_in_zip = os.path.join(path_inside_zip, child.value)
                full_file_path = os.path.join(full_path, child.value)
                if child.value.endswith(".zip"):
                    current_zip = self._extract_zip_from_zip(current_zip, path_in_zip, full_file_path)
                    path_in_zip = ""
                self._verify_paths_in_snapshot(child, current_zip, path_in_zip, full_file_path)
        else:
            self._check_file_exists(current_zip, path_inside_zip, full_path)

    def _check_file_exists(self, current_zip, path_inside_zip, whole_path):
        try:
            file = self._read_file_in_zip(current_zip, path_inside_zip)
            logger.info("file found: {}".format(whole_path))
            if len(file) == 0:
                err_msg = "the file is empty: {}".format(whole_path)
                raise InvalidSnapshotException(err_msg)
        except KeyError:
            err_msg = "file doesn't exist: {}".format(whole_path)
            raise InvalidSnapshotException(err_msg)

    def _extract_zip_from_zip(self, current_zip, path_inside_zip, full_path):
        try:
            zip_object = self._read_file_in_zip(current_zip, path_inside_zip)
            current_zip = BytesIO(zip_object)
        except KeyError:
            err_msg = "archive not found: {}".format(full_path)
            raise InvalidSnapshotException(err_msg)
        return current_zip

    def _read_file_in_zip(self, zip, path_inside_zip):
        with ZipFile(zip, "r") as zipfile:
            file = zipfile.read(path_inside_zip)
        return file


class Node(object):
    def __init__(self, value):
        self.value = value
        self.children = []

    def __str__(self):
        return self.value


class Tree(object):
    def __init__(self, root):
        self.root = Node(root)

    def add(self, values):
        self._add(values, self.root)

    def _add(self, values, node):
        if len(values) == 1:
            node.children.append(Node(values[0]))
        else:
            next_node = self._next_node(values[0], node)
            self._add(values[1:], next_node)

    def _next_node(self, value, node):
        next_node = self._get_child_node(node, value)
        if not next_node:
            next_node = self._get_new_node(node, value)
        return next_node

    def _get_child_node(self, node, value):
        for n in node.children:
            if n.value == value:
                return n

    def _get_new_node(self, node, value):
        new_node = Node(value)
        node.children.append(new_node)
        return new_node


class CheckSnapshot(object):

    def __init__(self, data_source):
        """
        Class used to check if the files contained in a snapshot archive contain the files specified in a dictionary
        or a JSON file.
        :param data_source: dict or path to a JSON file containing the names of the files that need to be checked
        in the snapsnot archive
        Structure of the dict or JSON file:
        {
             "mandatory_file": [
                 ".*log1.txt",
                 ".*file2.log"
             ],
             "not_mandatory_file": [
                 ".*not_mandatory_file3.log",
                 ".*file.txt"
             ]
        }
        """
        self.data_dict = None
        self.result_dict = {}
        self.not_found = []
        self.empty_file = []
        self.fail_test_not_found_file = False
        self.fail_test_zero_size_file = False
        self._set_data_dict(data_source)

    def _set_data_dict(self, data_source):
        """
        Set data_dict variable based on the type of data_source parameter which can be a dict or a JSON file
        :param data_source: dict or path to a JSON file containing the names of the files that need to be checked
        in the snapsnot archive
        """
        if isinstance(data_source, str):
            with open(data_source, "r") as fh:
                self.data_dict = json.load(fh)
        elif isinstance(data_source, dict):
            self.data_dict = data_source

    def validate_snapshot(self, files_from_zip):
        """
        Vaildate snapshot according to data obtained from trbl or csv file.
        :param files_from_zip: dictionary obtained from method content_zip()
        in class ContentSnapshot.
        """
        for name_from_zip, file_data in files_from_zip.items():
            for i in range(0, len(file_data), 2):
                path_size = [file_data[i], file_data[i + 1]]
                for key_j, val_j in self.data_dict.items():
                    self._check_snapshot_content(key_j, name_from_zip, path_size, val_j)
        self.not_found = self._not_matched_file()
        self._log_not_found_file()
        self._log_zero_size_file()

    def create_table(self):
        """
        Create table with three columns:
            Pattern: pattern used to search file.
            File: localization: Path to file in archive.
            Size: size file.
        :return: table.
        """
        table = []
        for key, value in self.result_dict.items():
            table.append([key, value[0][0], value[0][1]])
            [table.append(["", item[0], item[1]]) for item in value[1:]]
        if self.not_found:
            [table.append([item, " - ", " - "]) for item in self.not_found]
        return table

    def final_verdict(self):
        """
        Final verdict, if didn't find at least one mandatory file raise
        NotFoundMandatoryFile error or if at least size of one file is equal
        zero raise FileSizeEqualZero.
        """
        if self.fail_test_not_found_file:
            raise NotFoundMandatoryFile
        elif self.fail_test_zero_size_file:
            raise FileSizeEqualZero

    def _check_snapshot_content(self, key_j, name_from_zip, path_size, val_j):
        for name_file in val_j:
            if re.match(name_file, name_from_zip):
                self._check_file(name_file, path_size)

    def _check_file(self, name_file, path_size):
        if name_file not in self.result_dict:
            self.result_dict.setdefault(name_file, []).append([path_size[0], path_size[1]])
            self._is_size_equal_zero(name_file, path_size)
        else:
            self.result_dict[name_file].append([path_size[0], path_size[1]])
            self._is_size_equal_zero(name_file, path_size)

    def _is_size_equal_zero(self, name_file, path_size):
        if int(path_size[1]) == 0:
            self.empty_file.append([name_file, path_size[0], path_size[1]])

    def _log_zero_size_file(self):
        if self.empty_file:
            for EmptyFile in self.empty_file:
                logger.error("{} {}".format(os.path.split(EmptyFile[1])[-1], "size file is equal 0!"))
                self.fail_test_zero_size_file = True

    def _log_not_found_file(self):
        if self.not_found:
            for NotFoundFile in self.not_found:
                if NotFoundFile in self.data_dict["mandatory_file"]:
                    logger.error("{} {}".format(NotFoundFile, "not found!"))
                    self.fail_test_not_found_file = True
                else:
                    logger.debug("{} {}".format(NotFoundFile, "not found! (Not mandatory file)"))

    def _not_matched_file(self):
        not_matched_file = []
        if len(self.result_dict) != (len(self.data_dict["mandatory_file"]) + len(self.data_dict["not_mandatory_file"])):
            for _, value in self.data_dict.items():
                for item in value:
                    self._append_if_not_in_result_dict(item, not_matched_file)
            return not_matched_file
        return False

    def _append_if_not_in_result_dict(self, file_name, not_matched_file):
        if file_name not in self.result_dict:
            not_matched_file.append(file_name)
